 @Test void computesBusinessResult(){var result=service.execute(sample());assertEquals(false,result.get("valid"));assertEquals(1,((List<?>)result.get("conflicts")).size());assertEquals(List.of(),result.get("latestPublished"));}
 /** 上海如静知华信息科技有限公司 · https://www.zhuatech.cn/ 商业授权或定制开发请微信添加微信号zhuatech或zhuatech2进行咨询。 */
